"""Read-only summaries of obs and must node records."""
import json
import os
from pathlib import Path
import re
import stat
import sys
from collections import Counter


def reject_constant(value):
    raise ValueError("non-JSON constant: " + value)


def strict_json(data):
    return json.loads(data, parse_constant=reject_constant)


def record_files(node, channel):
    numbered = []
    active = None
    with os.scandir(node) as entries:
        for entry in entries:
            if not entry.is_file(follow_symlinks=False):
                continue
            match = re.fullmatch(rf"{channel}\.([0-9]{{12}})\.jsonl", entry.name)
            if match:
                numbered.append((int(match.group(1)), entry.name))
            elif entry.name == channel + ".active.jsonl":
                active = entry.name
    names = [name for _, name in sorted(numbered)]
    if active is not None:
        names.append(active)
    return names


def read_records(node, channel, bad):
    counts = Counter()
    for name in record_files(node, channel):
        parts = (node / name).read_bytes().split(b"\n")
        for line, raw in enumerate(parts[:-1], 1):
            try:
                value = strict_json(raw)
            except (ValueError, UnicodeError):
                bad.append({"file": name, "line": line, "why": "bad_json"})
                continue
            seq = value.get("seq") if isinstance(value, dict) else None
            if type(seq) is not int or seq < 1:
                bad.append({"file": name, "line": line, "why": "no_seq"})
            else:
                counts[seq] += 1
        if parts[-1]:
            bad.append({"file": name, "line": len(parts), "why": "torn"})
    return counts


def read_state(node):
    path = node / "state.json"
    try:
        info = path.lstat()
    except FileNotFoundError:
        return None, False
    try:
        if not stat.S_ISREG(info.st_mode):
            raise ValueError("state is not a regular file")
        value = strict_json(path.read_bytes())
        if not isinstance(value, dict) or not isinstance(value.get("channels"), dict):
            raise ValueError("invalid state structure")
        return value["channels"], False
    except (OSError, ValueError, UnicodeError):
        return None, True


def summarize(node):
    bad = []
    result = {}
    distinct = {}
    for channel in ("obs", "must"):
        counts = read_records(node, channel, bad)
        seqs = sorted(counts)
        distinct[channel] = seqs
        missing = [[a + 1, b - 1] for a, b in zip(seqs, seqs[1:]) if b > a + 1]
        result[channel] = {
            "count": sum(counts.values()),
            "first": seqs[0] if seqs else None,
            "last": seqs[-1] if seqs else None,
            "missing": missing,
            "dup": [seq for seq in seqs if counts[seq] >= 2],
            "next_seq": None,
            "unacked": None,
            "stale_next": None,
        }
    states, invalid = read_state(node)
    if states is not None:
        for channel in ("obs", "must"):
            state = states.get(channel)
            if (not isinstance(state, dict)
                    or type(state.get("next_seq")) is not int
                    or (channel == "must" and type(state.get("acked_upto")) is not int)):
                invalid = True
                continue
            item = result[channel]
            item["next_seq"] = state["next_seq"]
            if channel == "must":
                item["unacked"] = sum(seq > state["acked_upto"] for seq in distinct[channel])
            if item["last"] is not None:
                item["stale_next"] = state["next_seq"] != item["last"] + 1
    if invalid:
        bad.append({"file": "state.json", "line": None, "why": "bad_state"})
    bad.sort(key=lambda item: (item["file"], item["line"] or 0, item["why"]))
    return {"v": 1, "channels": result, "bad": bad}


def main(argv=None):
    args = sys.argv[1:] if argv is None else argv
    if len(args) != 1 or not Path(args[0]).is_dir():
        return 2
    try:
        answer = summarize(Path(args[0]))
    except OSError:
        return 2
    print(json.dumps(answer, ensure_ascii=False, separators=(",", ":")))
    return 0


if __name__ == "__main__":
    sys.exit(main())
